import { afterAll, describe, expect, it } from 'vitest';
import '@lancedb/lancedb/embedding/openai';
import { randomUUID } from 'node:crypto';
import type { WebSource } from '../search-sources';
import { MarkdownElementType } from '../types';
import {
  deleteIndex,
  embedder,
  indexDatasetSources,
  queryDatasetSources,
} from './engine';

afterAll(async () => {
  await deleteIndex();
});

const accessToken = [REDACTED];
describe(
  'search engine',
  () => {
    it('should embed some data', async () => {
      const embeddings = await embedder(['hello world', 'goodbye world'], {
        accessToken,
      });

      expect(embeddings).toHaveLength(2);
    });

    it('should index a dataset web source', async () => {
      const indexedItems = await indexDatasetSources({
        dataset: {
          id: randomUUID(),
          name: 'my-test_dataset',
        },
        sources: [
          {
            url: 'https://example.com',
            title: 'Example',
            contentType: 'web',
            markdownTree: undefined,
          },
        ],
        options: {
          accessToken,
        },
      });

      expect(indexedItems).toBe(0);
    });

    it('should index a dataset web source with markdown tree', async () => {
      const indexedItems = await indexDatasetSources({
        dataset: {
          id: randomUUID(),
          name: 'test dataset',
        },
        sources: [
          {
            url: 'https://example.com',
            title: 'Example',
            contentType: 'web',
            markdownTree: {
              type: MarkdownElementType.Header,
              level: 0,
              content: 'Example',
              children: [
                {
                  type: MarkdownElementType.Paragraph,
                  content: 'This is an example paragraph.',
                  parent: null,
                },
              ],
              parent: null,
            },
          },
        ],
        options: {
          accessToken,
        },
      });

      expect(indexedItems).toBe(2);
    });

    it("should return a matched dataset's web source when querying", async () => {
      const dataset = {
        id: randomUUID(),
        name: 'my-test_dataset',
      };

      const sources = [
        {
          url: 'https://example.com',
          title: 'Example',
          contentType: 'web',
          markdownTree: {
            type: MarkdownElementType.Header,
            level: 0,
            content: 'Title',
            children: [
              {
                type: MarkdownElementType.Paragraph,
                content: 'hello world',
                parent: null,
              },
              {
                type: MarkdownElementType.Paragraph,
                content: 'goodby world',
                parent: null,
              },
            ],
            parent: null,
          },
        },
      ] as WebSource[];

      await indexDatasetSources({
        dataset,
        sources,
        options: {
          accessToken,
        },
      });

      const results = await queryDatasetSources({
        dataset,
        query: 'greetings',
        options: { accessToken },
      });

      const mostSimilar = results[0];

      expect(mostSimilar.text).toBe('hello world\n\n');
    });
  },

  {
    timeout: 100_000,
  },
);

import type { RequestEvent } from '@builder.io/qwik-city';
import { saveAnonymousSession } from '~/services/auth/session';

export const onRequest = async (event: RequestEvent) => {
  const { sharedMap, cookie } = event;

  const session = cookie.get('session');
  const anonymous = cookie.get('anonymous');

  if (session) {
    sharedMap.set('session', session.json());

    return;
  }

  if (anonymous) {
    sharedMap.set('anonymous', anonymous.json());

    return;
  }

  await saveAnonymousSession(event);
};

import { isDev } from '@builder.io/qwik';
import type { CookieOptions, RequestEvent } from '@builder.io/qwik-city';
import type { Session } from '~/state';

export const saveSession = async (event: RequestEvent, session: Session) => {
  const { cookie, sharedMap } = event;
  const options: CookieOptions = {
    sameSite: 'none',
    secure: true,
    httpOnly: !isDev,
    path: '/',
  };

  try {
    const decodedToken = JSON.parse(
      Buffer.from(session.token.split('.')[1], 'base64').toString(),
    );

    options.maxAge = decodedToken.exp - decodedToken.iat;
  } catch (e) {
    console.error(e);
  }

  cookie.delete('session');
  cookie.set('session', session, options);
  sharedMap.set('session', session);
};

export const saveAnonymousSession = async (event: RequestEvent) => {
  const { cookie, sharedMap } = event;
  const random = crypto.randomUUID();
  const session = {
    anonymous: true,
    user: {
      username: random,
    },
  };

  cookie.delete('anonymous');
  cookie.set('anonymous', session, {
    sameSite: 'none',
    secure: true,
    httpOnly: !isDev,
    maxAge: 60 * 60 * 24 * 365,
    path: '/',
  });
  sharedMap.set('anonymous', session);
};

import { isDev } from '@builder.io/qwik';
import type { RequestEvent } from '@builder.io/qwik-city';
import * as hub from '@huggingface/hub';
import { appConfig } from '~/config';
import { saveSession } from '~/services/auth/session';
import type { Session } from '~/state/session';

export const onGet = async (event: RequestEvent) => {
  const {
    authentication: { clientId, hfToken },
  } = appConfig;

  if (clientId) return handleOAuthLogin(event);

  if (hfToken) return handleHFTokenLogin(event);

  throw Error('Missing HF_TOKEN or OAUTH_CLIENT_ID');
};

const handleOAuthLogin = async ({ url, cookie, redirect }: RequestEvent) => {
  const sessionCode = crypto.randomUUID();

  const {
    authentication: { clientId, scopes, httpsOnly },
  } = appConfig;

  const redirectOrigin = httpsOnly
    ? url.origin.replace('http://', 'https://')
    : url.origin;

  const authData = {
    state: sessionCode,
    clientId: clientId!,
    scopes,
    redirectUrl: `${redirectOrigin}/auth/callback/`,
    localStorage: {
      codeVerifier: undefined,
      nonce: undefined,
    },
  };

  const loginUrl = await hub.oauthLoginUrl(authData);

  cookie.set(
    sessionCode,
    {
      codeVerifier: authData.localStorage.codeVerifier!,
      nonce: authData.localStorage.nonce!,
    },
    {
      sameSite: 'none',
      secure: true,
      httpOnly: !isDev,
      path: '/auth/callback',
    },
  );
  throw redirect(303, loginUrl);
};

const handleHFTokenLogin = async (event: RequestEvent) => {
  const { redirect } = event;

  const {
    authentication: { hfToken },
  } = appConfig;

  try {
    const userInfo = (await hub.whoAmI({ accessToken: hfToken! })) as any;

    const session: Session = {
      anonymous: false,
      token: hfToken!,
      user: {
        name: userInfo.fullname,
        username: userInfo.name,
        picture: userInfo.avatarUrl,
      },
    };

    saveSession(event, session);
  } catch (e: any) {
    throw Error(`Invalid HF_TOKEN: ${e.message}`);
  }

  throw redirect(303, '/');
};

import type { RequestEvent } from '@builder.io/qwik-city';
import * as hub from '@huggingface/hub';
import { saveSession } from '~/services/auth/session';

export const onGet = async (event: RequestEvent) => {
  const { cookie, redirect, query, url } = event;

  const code = query.get('code');
  const stateParam = query.get('state');

  if (!code || !stateParam) {
    throw redirect(303, '/');
  }

  const { state: sessionCode, nonce: nonceFromCallback } =
    JSON.parse(stateParam);

  if (!cookie.has(sessionCode)) {
    throw redirect(303, '/');
  }

  const data = cookie.get(sessionCode)!;
  const { codeVerifier, nonce } = data.json<any>();

  if (nonce !== nonceFromCallback) {
    throw redirect(303, '/');
  }

  try {
    cookie.delete(sessionCode);

    const auth = await hub.oauthHandleRedirect({
      codeVerifier,
      nonce,
      redirectedUrl: url.href,
    });

    const session = {
      anonymous: false,
      token: [REDACTED],
      user: {
        name: auth.userInfo.name,
        username: auth.userInfo.preferred_username,
        picture: auth.userInfo.picture,
      },
    };

    saveSession(event, session);
  } catch (e) {
    console.error(e);
  }

  throw redirect(308, '/');
};

import {
  component$,
  isServer,
  useSignal,
  useVisibleTask$,
} from '@builder.io/qwik';

export default component$(() => {
  const accessToken = [REDACTED] | null>(null);

  useVisibleTask$(() => {
    if (isServer) return;

    accessToken.value =
      document.location.hash
        .slice(1) // Remove the leading '#'
        .split('&')
        .map((param) => param.split('='))
        .filter(([key]) => key === 'access_token')[0]?.[1] || null;
  });

  return (
    <div class="flex flex-col h-full w-fit overflow-hidden ml-4 mt-4">
      <h1 class="text-2xl font-bold">Add from Google Drive</h1>

      <p class="text-sm mt-4 gray-500">Click on the token area to copy</p>

      <pre
        class="flex flex-col mt-2 rounded-md p-4 w-fit"
        style="width: 70%; word-break: break-all; white-space: pre-wrap;"
      >
        <code
          id="access-token-code"
          class="text-m mt-8 border border-gray-300 bg-gray-100 rounded-md p-4 w-fit cursor-pointer"
          onClick$={() => {
            navigator.clipboard.writeText(accessToken.value || '');
            const codeElement = document.getElementById('access-token-code')!;
            const tooltip = document.createElement('div');
            tooltip.textContent = 'Copied!';
            tooltip.className =
              'absolute bg-gray-800 text-white text-sm rounded-md p-2';

            tooltip.style.opacity = '1';
            tooltip.style.top = `${codeElement.getBoundingClientRect().top}px`;
            tooltip.style.left = '70%';
            tooltip.style.transform = 'translate(-50%, -100%)';
            tooltip.style.zIndex = '1000';
            tooltip.style.transition =
              'transform 0.3s ease-in-out, opacity 0.3s ease-in-out';

            document.body.appendChild(tooltip);

            setTimeout(() => {
              document.body.removeChild(tooltip);
            }, 1000);
          }}
        >
          {accessToken.value}
        </code>
      </pre>
    </div>
  );
});

import {
  component$,
  useSignal,
  useTask$,
  useVisibleTask$,
} from '@builder.io/qwik';
import { cn } from '@qwik-ui/utils';
import {
  LuArrowUpRight,
  LuGlobe,
  LuThumbsUp,
  LuX,
} from '@qwikest/icons/lucide';
import { Button } from '~/components';
import { Tooltip } from '~/components/ui/tooltip/tooltip';
import { type Cell, useColumnsStore } from '~/state';
import { useValidateCellUseCase } from '~/usecases/validate-cell.usecase';

function getDomain(url: string): string {
  try {
    const { hostname } = new URL(url);
    return hostname;
  } catch {
    return url;
  }
}

export const CellActions = component$<{ cell: Cell }>(({ cell }) => {
  const { columns } = useColumnsStore();
  const validateCell = useValidateCellUseCase();
  const showSourcesModal = useSignal(false);
  const isStatic = useSignal(false);

  useTask$(({ track }) => {
    track(() => columns.value);
    const cellColumn = columns.value.find((col) => col.id === cell.column?.id);
    isStatic.value = cellColumn?.kind === 'static';
  });

  useVisibleTask$(() => {
    const handler = () => {
      showSourcesModal.value = false;
    };
    window.addEventListener('closeAllSourcesModals', handler);
    return () => window.removeEventListener('closeAllSourcesModals', handler);
  });

  if (isStatic.value) return null;

  return (
    <>
      <div class="absolute h-full w-full z-40 bottom-0 right-0">
        <div class="flex flex-col items-end justify-center w-full h-full">
          <div class="flex flex-col justify-end items-center gap-1 h-full p-2">
            <Button
              look="ghost"
              size="sm"
              class={cn(
                'opacity-0 group-hover:opacity-100 transition-opacity visible rounded-full w-[30px] h-fit text-white bg-neutral-600 p-2 hover:shadow-md shadow-neutral-700 hover:bg-neutral-700',
                {
                  hidden: !cell.value || !cell.sources?.length,
                },
              )}
              onClick$={() => {
                if (cell.sources?.length) {
                  window.dispatchEvent(
                    new CustomEvent('closeAllSourcesModals'),
                  );
                  showSourcesModal.value = true;
                }
              }}
            >
              <Tooltip text="View sources" floating="right" gutter={12}>
                <LuGlobe class="text-sm" />
              </Tooltip>
            </Button>
            <Button
              look="ghost"
              size="sm"
              class={cn(
                'opacity-0 group-hover:opacity-100 transition-opacity visible rounded-full w-[30px] h-fit text-white bg-neutral-600 p-2 hover:shadow-md shadow-neutral-700 hover:bg-neutral-700',
                {
                  'bg-secondary-400 shadow-secondary-400 hover:bg-secondary-400 hover:text-secondary-200 opacity-100':
                    cell.validated,
                  hidden: !cell.value,
                },
              )}
              onClick$={() => {
                validateCell(cell, cell.value, !cell.validated);
              }}
            >
              <Tooltip
                text="Mark as a good example"
                floating="right"
                gutter={12}
              >
                <LuThumbsUp class="text-sm" />
              </Tooltip>
            </Button>
          </div>
        </div>
      </div>

      {showSourcesModal.value && (
        <div
          stoppropagation:click
          class="fixed top-0 right-0 h-full w-[400px] z-[100] bg-white border-l border-neutral-300 shadow-lg flex flex-col sources-side-modal"
          style={{ minHeight: '100vh' }}
          window:onCloseSourcesModal$={() => {
            showSourcesModal.value = false;
          }}
        >
          <div class="flex justify-between items-center p-4 border-b border-neutral-200">
            <span class="font-semibold text-lg text-neutral-700">Sources</span>
            <Button
              look="ghost"
              class="p-1.5 rounded-full hover:bg-neutral-200 cursor-pointer"
              onClick$={() => {
                showSourcesModal.value = false;
              }}
              aria-label="Close"
            >
              <LuX class="text-lg text-neutral" />
            </Button>
          </div>
          <div class="flex-1 overflow-y-auto p-4">
            <ul class="ml-2 mt-2 space-y-4">
              {(() => {
                if (!cell.sources) return null;
                // Group unique snippets by URL
                const grouped = cell.sources.reduce(
                  (acc, source) => {
                    const normalizedSnippet = source.snippet
                      .trim()
                      .replace(/\s+/g, ' ');
                    if (!acc[source.url]) acc[source.url] = [];
                    if (!acc[source.url].some((s) => s === normalizedSnippet)) {
                      acc[source.url].push(normalizedSnippet);
                    }
                    return acc;
                  },
                  {} as Record<string, string[]>,
                );
                return Object.entries(grouped).map(([url, snippets]) => {
                  const domain = getDomain(url);
                  return (
                    <div
                      key={url}
                      class="bg-white p-4 transition-colors cursor-pointer hover:bg-neutral-100 hover:rounded-sm source-group"
                      onClick$={() => window.open(url, '_blank')}
                      tabIndex={0}
                      role="button"
                      aria-label={`Open source: ${domain}`}
                    >
                      <div class="flex items-center justify-between">
                        <span class="text-neutral-600 font-medium text-xs source-domain">
                          {domain}
                        </span>
                        <LuArrowUpRight class="text-neutral text-base ml-2" />
                      </div>
                      <ul class="ml-2 mt-2 space-y-4">
                        {snippets.map((snippet, j) => {
                          if (!snippet) return null;
                          return (
                            <li
                              key={j}
                              class="block text-primary-600 whitespace-pre-line text-sm"
                            >
                              {snippet} ...
                            </li>
                          );
                        })}
                      </ul>
                    </div>
                  );
                });
              })()}
            </ul>
          </div>
        </div>
      )}
    </>
  );
});

import type { RequestEventBase } from '@builder.io/qwik-city';
import { server$ } from '@builder.io/qwik-city';

import { INFERENCE_PROVIDERS } from '@huggingface/inference';
import { appConfig } from '~/config';
import { cacheGet, cacheSet } from '~/services/cache';
import { type Session, type TaskType, useServerSession } from '~/state';

// This list helps to exclude providers that are not supported by the endpoint
const UNSUPPORTED_PROVIDERS = ['openai', 'nscale', 'ovhcloud'];

const MODEL_EXPANDABLE_KEYS = [
  'author',
  //'cardData',
  //'config',
  'createdAt',
  //'disabled',
  'downloads',
  //'downloadsAllTime',
  //'gated',
  //'inference',
  'inferenceProviderMapping',
  //'lastModified',
  //'library_name',
  'likes',
  //'mask_token',
  //'model-index',
  //'pipeline_tag',
  'private',
  'safetensors',
  //'sha',
  //'siblings',
  //'spaces',
  'tags',
  //'transformersInfo',
  'trendingScore',
  //'widgetData',
  //'gguf',
  //'resourceGroup',
];

export interface Model {
  id: string;
  supportedType: string;
  providers?: string[];
  endpointUrl?: string;
  tags?: string[];
  safetensors?: unknown;
  size?: string;
  pipeline_tag?: string;
  trendingScore?: number;
  picture?: string;
}

const cachedOrgAvatars: Record<string, string> = {};

const fetchAvatar = async (modelId: string): Promise<string | undefined> => {
  const org = modelId.split('/')[0];
  if (cachedOrgAvatars[org] !== undefined) {
    return cachedOrgAvatars[org];
  }

  try {
    const response = await fetch(
      `https://huggingface.co/api/organizations/${org}/avatar`,
    );
    const data = await response.json();

    if (response.ok && data?.avatarUrl) {
      cachedOrgAvatars[org] = data.avatarUrl;
      return data.avatarUrl;
    }
  } catch {
    cachedOrgAvatars[org] = '';
  }

  return undefined;
};

const listTextGenerationModels = async (
  session: Session,
  limit?: number,
): Promise<Model[]> => {
  const textModels = await fetchModelsForPipeline(
    session,
    'text-generation',
    limit,
  );

  return textModels
    .flat()
    .map((model) => ({
      ...model,
      supportedType: 'text',
    }))
    .sort((a, b) => (b.trendingScore || 0) - (a.trendingScore || 0));
};

const listAllImageTextToTextModels = async (
  session: Session,
  limit?: number,
): Promise<Model[]> => {
  const imageTextToTextModels = await fetchModelsForPipeline(
    session,
    'image-text-to-text',
    limit,
  );

  return imageTextToTextModels
    .map((model) => ({
      ...model,
      supportedType: 'image-text-to-text',
    }))
    .sort((a, b) => (b.trendingScore || 0) - (a.trendingScore || 0));
};

const listTextToImageModels = async (
  session: Session,
  limit?: number,
): Promise<Model[]> => {
  const imageModels = await fetchModelsForPipeline(
    session,
    'text-to-image',
    limit,
  );

  return imageModels
    .map((model) => ({
      ...model,
      supportedType: 'image',
    }))
    .sort((a, b) => (b.trendingScore || 0) - (a.trendingScore || 0));
};

const listImageToImageModels = async (
  session: Session,
  limit?: number,
): Promise<Model[]> => {
  const imageToImageModels = await fetchModelsForPipeline(
    session,
    'image-to-image',
    limit,
  );

  return imageToImageModels
    .map((model) => ({
      ...model,
      supportedType: 'image-to-image',
    }))
    .sort((a, b) => (b.trendingScore || 0) - (a.trendingScore || 0));
};

const listAllModels = async (session: Session): Promise<Model[]> => {
  // Fetch models for all supported generation types
  const limit = 300;
  const models = await Promise.all([
    // All text generation models that support conversational
    listTextGenerationModels(session, limit),
    // All image-text-to-text models
    listAllImageTextToTextModels(session, limit),
    // All image-to-image models
    listImageToImageModels(session, limit),
    // All image generation models
    // TODO: Add pagination support since image generation models can be large
    // and we might want to fetch more than just the first 1000 models.
    listTextToImageModels(session, limit),
  ]);

  return await Promise.all(
    models.flat().map(async (m) => ({
      ...m,
      picture: await fetchAvatar(m.id),
    })),
  );
};

const fetchModelsForPipeline = async (
  session: Session,
  kind: TaskType,
  limit?: number,
  timeout: number = 1000,
): Promise<Model[]> => {
  const cacheKey = { kind, limit, session };
  const cachedValue = cacheGet(cacheKey);

  if (cachedValue) {
    return cachedValue as Model[];
  }

  const url = 'https://huggingface.co/api/models';

  const params = new URLSearchParams([
    ...Object.entries({
      pipeline_tag: kind,
      sort: 'trendingScore',
      direction: '-1',
    }),
    ...INFERENCE_PROVIDERS.filter(
      (m) => !UNSUPPORTED_PROVIDERS.includes(m),
    ).map((provider) => ['inference_provider', provider]),
    ...MODEL_EXPANDABLE_KEYS.map((key) => ['expand', key]),
  ]);

  if (limit) {
    params.append('limit', `${limit}`);
  }

  const {
    authentication: { hfToken },
    inference: { excludedHubModels },
  } = appConfig;

  const token = [REDACTED] ? hfToken : [REDACTED];
  const headers: HeadersInit = {};
  if (token) {
    headers['Authorization'] = `Bearer ${token}`;
  }

  try {
    const response = await fetch(`${url}?${params.toString()}`, {
      method: 'GET',
      headers,
      signal: timeout ? AbortSignal.timeout(timeout) : undefined,
    });

    if (!response.ok) {
      const message = await response.text();
      console.warn(`Failed to fetch ${kind} models`, response.status, message);
      return [];
    }

    const data: any[] = await response.json();

    const models = data.reduce((acc: Model[], model) => {
      const providers = model.inferenceProviderMapping;

      if (!providers?.length) return acc;

      const availableProviders = providers
        .filter((provider: any) => provider.status === 'live')
        .map((provider: any) => provider.provider);

      if (
        availableProviders.length > 0 &&
        !excludedHubModels.includes(model.id)
      ) {
        let sizeInB = 0;
        if (model.safetensors) {
          const paramCounts = Object.entries(
            model.safetensors.parameters || {},
          ).map(([_, value]) => Number(value));

          sizeInB = Math.max(...paramCounts) / 1e9;
        }

        let size: string | undefined;
        if (Number.isFinite(sizeInB) && sizeInB > 0) {
          size = `${Math.floor(sizeInB)}B`;
        }

        acc.push({
          ...model,
          providers: availableProviders,
          size,
          pipeline_tag: kind,
        });
      }

      return acc;
    }, []) as Model[];

    cacheSet(cacheKey, models);

    return models;
  } catch (error) {
    console.warn(`Unexpected error getting models`, String(error));
    return [];
  }
};

export const useHubModels = () =>
  server$(async function (
    this: RequestEventBase<QwikCityPlatform>,
  ): Promise<Model[]> {
    const session = useServerSession(this);
    if (!session) return [];

    const { customModels = [] } = appConfig.inference.tasks.textGeneration;
    // Remove this constant when we want tu support custom models and HF models at the same time
    const hideHFModels = customModels.length > 0;

    if (hideHFModels) {
      const limit = 100;
      const [imageModels, imageTextToTextModels] = await Promise.all([
        listTextToImageModels(session, limit),
        listAllImageTextToTextModels(session, limit),
      ]);

      return [...customModels, ...imageModels, ...imageTextToTextModels];
    }

    const models = await listAllModels(session);

    const {
      inference: {
        tasks: { textGeneration },
      },
    } = appConfig;

    if (models.length === 0) {
      return [
        {
          id: textGeneration.defaultModel,
          providers: [textGeneration.defaultProvider],
          tags: ['conversational'],
          safetensors: {},
          pipeline_tag: 'text-generation',
          supportedType: 'text',
        },
        // TODO: Add default image model if needed
      ];
    }

    return models;
  });

export interface TrendingModel {
  id: string;
  picture?: string;
}

export const useTrendingHubModels = () =>
  server$(async function (
    this: RequestEventBase<QwikCityPlatform>,
  ): Promise<TrendingModel[]> {
    console.log('Fetching trending models... from url', this.request.url);
    const session = useServerSession(this);
    if (!session) return [];

    const models = await Promise.all([
      fetchModelsForPipeline(session, 'text-generation', 1),
      fetchModelsForPipeline(session, 'text-to-image', 1),
      fetchModelsForPipeline(session, 'image-text-to-text', 1),
      fetchModelsForPipeline(session, 'image-to-image', 1),
    ]);

    return await Promise.all(
      models
        .flat()
        .filter((m) => !!m)
        .map(async (m) => ({
          id: m.id,
          picture: await fetchAvatar(m.id),
        })),
    );
  });

